namespace Gordic.Bar.WebClient {
    var gcontent = Decorators.gcontent;

    @gcontent
    export class GBarVerze extends GContentBase {

        title = "Přehled balančních verzí"; //aby se dalo přistoupit z breadcrumbs, je nastaveno zde místo v C#
        taskId = "actSeznamPozadavku"; // označení položky v taskListu

        private modelbar: Gordic.Bar.Interface.GBarsverDto[];
        private row: Gordic.Bar.Interface.GBarsverDto | null = null;;

        //        private globals = Gordic.Bar.Globals.GAdaGlobals;
//        private readonly globals: Gordic.Bar.WebClient.GBarGlobalsDto;

        private view_ISL: Gordic.Isl.View<Gordic.Bar.Interface.GBarsverDto>;

        onContentReady() {

            var that = this;
            var $tab = $(this.contentDiv);

            $tab.empty();

            var mainForm = $("<div>").appendTo(this.element).gform("setup", { layoutDescriptor: "L1M1S1 LMS-0-12-0" }).gformsection("create");

            var $mainTable = $("<div>")
                //.css("height", "100%")
                .appendTo(mainForm)
                .gautofit()
                .ggrid({
                    columnMode: "full",

                    selection: function(ev, ctx) {
                        that.row = $mainTable.ggrid("activeRow");
                        if (that.row !== null) {
                        }
                    },

                    searchColumns: ["*verze_c", "*verze_k", "*popis"],
                    columns: new Gordic.Data.GridFormat()
                        //.addIconColumn({
                        //    name: "aktivita",
                        //    field: "aktivita",
                        //    caption: "Stav",
                        //    // width: 25,
                        //    formatPreset: Gordic.Global.Enums.GridColumnFormatIcon.icon,
                        //    iconTemplate: function (data) {
                        //        switch (data.aktivita) {
                        //            case 100: return { icon: "fa-check-circle-o g-state-success g-state-text", text: "Aktivní", caption: "Aktivní", tooltip: "Aktivní" };
                        //            case 300: return { icon: "fa-check-circle g-state-warning g-state-text", text: "Návrh", caption: "Návrh", tooltip: "Návrh" };
                        //            case 500: return { icon: "fa-trash g-state-error g-state-text", text: "Neaktivní", caption: "Neaktivní", tooltip: "Neaktivní" };
                        //            default: return null;
                        //        }
                        //    }
                        //})
                        .addTextColumn({
                            name: "komp_dec_txt",
                            caption: "Kompetence",
                            width: 200
                        })
                        .addTextColumn({
                            name: "verze_c",
                            caption: "Cen.",
                            align: "center",
                            width: 50
                        })
                        .addNumberColumn({
                            name: "verze_k",
                            caption: "Dec.",
                            align: "center",
                            width: 50
                        })
                        .addTextColumn({               
                            name: "popis",
                            caption: "Popis",
                            width: 400
                        })
                        .addDateTimeColumn({
                            name: "dat_zmena",
                            caption: "Datum změny",
                            customClass: "dt-left",
                            width: 140,
                        })
                        .addTextColumn({               
                            name: "zmenu_prov_txt",
                            caption: "Změnu provedl",
                            width: 400
                        })
                });

            that.view_ISL = new Gordic.Isl.View(this.isl.BalancniVerze.list({ }));

            $mainTable.ggrid("setData", that.view_ISL);

        }
    }
}
